/**
 * Coordination of runtime instances that run the same flows.
 *
 * The runtime uses exactly one coordination plugin. It is selected only
 * explicitly with the `coordination` setting:
 *
 * ```js
 * coordination: { plugin: "<plugin id>", options: { ... } }
 * ```
 *
 * Without the setting the built-in local plugin is used: the process is the
 * only instance, always the leader, and claims are kept in memory. Installing
 * a module with a coordination plugin does not change the behaviour.
 *
 * ## Coordination plugins
 *
 * A plugin is registered by a module like any other plugin:
 *
 * ```js
 * module.exports = function(RED) {
 *     RED.plugins.registerPlugin("my-coordination", {
 *         type: "node-red-coordination",
 *         start: async ({instanceId, processId, options, log}) => { ... },
 *         stop: async () => { ... },
 *         resign: async () => { ... },
 *         isLeader: () => leader,
 *         onLeaderChange: (listener) => { ...; return () => { ... } },
 *         claim: async (key, ttlMs) => claimOrNull,
 *         status: () => ({connected})
 *     });
 * }
 * ```
 *
 * @typedef {Object} CoordinationPlugin
 * @property {"node-red-coordination"} type
 * @property {(ctx: {instanceId: string, processId: string, options: object, log: object}) => Promise<void>} start
 *   Connects to the coordinator. Called once, before the flows start. A
 *   rejection fails the start of the runtime (there is no fallback to the
 *   local plugin - it would run the coordinated tasks twice).
 *   `instanceId` is the instance id of the runtime settings - instances that
 *   share one storage share it as well; `processId` is random for each start
 *   of the process and identifies this process.
 * @property {() => Promise<void>} stop
 *   Gives up the leadership and releases the claims. Called by `runtime.stop()`
 *   after the flows have stopped.
 * @property {() => Promise<void>} [resign]
 *   Gives up the leadership without disconnecting. Called at the beginning of
 *   `runtime.stop()`, before the flows stop, so another instance takes over
 *   before a long stop of the flows.
 * @property {() => boolean} isLeader
 *   Synchronous; `false` without a confirmed leadership (including no connection).
 * @property {(listener: (isLeader: boolean) => void) => (() => void)} onLeaderChange
 *   Returns a function that removes the listener. The listener is called on
 *   every change, also with `false` when the connection is lost.
 * @property {(key: string, ttlMs: number) => Promise<Claim|null>} claim
 *   Atomic claim of a key in the whole cluster for ttlMs. `null` - the key is
 *   claimed by another instance (or earlier by this one). A rejection - no
 *   connection: the caller does NOT run the task.
 * @property {() => {connected: boolean}} [status]
 *
 * @typedef {Object} Claim
 * @property {string} key
 * @property {number} expiresAt - expiry time by the coordinator's clock, converted to the local clock
 * @property {() => Promise<void>} release
 * @property {(ttlMs: number) => Promise<boolean>} [renew] - `false` when the claim was lost
 *
 * ## Node api (`RED.coordination`)
 *
 * - `RED.coordination.isLeader()` - whether this instance is the leader (local plugin: always `true`)
 * - `RED.coordination.onLeaderChange(node, listener)` - the listener is removed
 *   automatically when the node closes; returns a function that removes it
 * - `RED.coordination.claim(key, ttlMs)` - `null` or a rejection: do not run the task;
 *   recommended key prefix: the node id
 * - `RED.coordination.info()` - `{plugin, local}`, without the plugin options
 *
 * Example - a node that consumes a subscription without load balancing only on
 * the leader:
 *
 * ```js
 * function QueueInNode(config) {
 *     RED.nodes.createNode(this, config);
 *     const node = this;
 *     function update(isLeader) {
 *         if (isLeader) { subscribe(node) } else { unsubscribe(node) }
 *     }
 *     if (RED.coordination) {
 *         RED.coordination.onLeaderChange(node, update);
 *         update(RED.coordination.isLeader());
 *     } else {
 *         update(true);
 *     }
 *     node.on("close", () => unsubscribe(node));
 * }
 * ```
 *
 * A leader may change while a task runs: a long task should stop on
 * `onLeaderChange(false)` or when `renew()` returns `false`. Whether two
 * instances can be leaders at once during a network partition depends on the
 * plugin.
 */

const crypto = require("crypto");
const {events, log} = require("@node-red/util");
const local = require("./local");

const PLUGIN_TYPE = local.PLUGIN_TYPE;
const LOCAL_PLUGIN_ID = "local";
const REQUIRED_FUNCTIONS = ["start", "stop", "isLeader", "onLeaderChange", "claim"];

function createError(code, message) {
    const err = new Error(message);
    err.code = code;
    return err;
}

/**
 * Creates a coordination facade. The runtime uses the instance exported by
 * this module; separate instances let the tests run several "instances" with
 * a shared coordinator in one process.
 */
function createCoordination() {
    let runtime = null;
    let plugin = null;
    let pluginId = LOCAL_PLUGIN_ID;
    let isLocal = true;
    let started = false;
    let stopping = false;
    let unsubscribePlugin = null;
    const listeners = new Set();

    function onPluginAdded(id) {
        if (!started || !runtime) {
            return;
        }
        const added = runtime.plugins.getPlugin(id);
        if (added && added.type === PLUGIN_TYPE) {
            log.warn(log._("coordination.plugin-added-after-start", {plugin: id, active: pluginId}));
        }
    }

    function onPluginLeaderChange(leader) {
        leader = leader === true;
        if (leader) {
            log.info(log._("coordination.leader-acquired", {plugin: pluginId}));
        } else if (stopping) {
            log.info(log._("coordination.leader-released", {plugin: pluginId}));
        } else {
            log.warn(log._("coordination.leader-lost", {plugin: pluginId}));
        }
        Array.from(listeners).forEach(function(listener) {
            try {
                listener(leader);
            } catch (err) {
                log.warn(log._("coordination.listener-error", {error: err.toString()}));
            }
        });
    }

    function selectPlugin() {
        const config = runtime.settings ? runtime.settings.coordination : undefined;
        const selected = config && typeof config === "object" ? config.plugin : undefined;
        if (selected === undefined || selected === null || selected === "") {
            const installed = runtime.plugins.getPluginsByType(PLUGIN_TYPE) || [];
            if (installed.length > 0) {
                log.warn(log._("coordination.plugin-not-selected", {
                    plugins: installed.map(p => p.id).join(", ")
                }));
            }
            return {id: LOCAL_PLUGIN_ID, plugin: local.create(), local: true, options: {}};
        }
        const found = typeof selected === "string" ? runtime.plugins.getPlugin(selected) : undefined;
        if (!found || found.type !== PLUGIN_TYPE) {
            throw createError("coordination.plugin-not-found",
                log._("coordination.plugin-not-found", {plugin: String(selected), type: PLUGIN_TYPE}));
        }
        const missing = REQUIRED_FUNCTIONS.filter(f => typeof found[f] !== "function");
        if (missing.length > 0) {
            throw createError("coordination.plugin-invalid",
                log._("coordination.plugin-invalid", {plugin: selected, missing: missing.join(", ")}));
        }
        return {id: selected, plugin: found, local: false, options: config.options || {}};
    }

    function getInstanceId() {
        try {
            return runtime.settings.get("instanceId") || "";
        } catch (err) {
            return "";
        }
    }

    /**
     * Selects and starts the coordination plugin. Resolves when the plugin is
     * ready; the runtime starts the flows only after that.
     * @param {Object} [_runtime] - the internal runtime api
     * @return {Promise<void>}
     */
    async function start(_runtime) {
        if (_runtime) {
            runtime = _runtime;
        }
        if (started) {
            return;
        }
        const selection = selectPlugin();
        await selection.plugin.start({
            instanceId: getInstanceId(),
            processId: crypto.randomBytes(8).toString("hex"),
            options: selection.options,
            log: log
        });
        plugin = selection.plugin;
        pluginId = selection.id;
        isLocal = selection.local;
        stopping = false;
        started = true;
        unsubscribePlugin = plugin.onLeaderChange(onPluginLeaderChange);
        events.removeListener("registry:plugin-added", onPluginAdded);
        events.on("registry:plugin-added", onPluginAdded);
        log.info(log._("coordination.using", {plugin: pluginId}));
    }

    /**
     * Gives up the leadership before the flows stop. Errors are logged.
     * @return {Promise<void>}
     */
    async function resign() {
        if (!started) {
            return;
        }
        stopping = true;
        if (typeof plugin.resign === "function") {
            try {
                await plugin.resign();
            } catch (err) {
                log.warn(log._("coordination.resign-failed", {error: err.toString()}));
            }
        }
    }

    /**
     * Stops the coordination plugin after the flows have stopped. Errors are logged.
     * @return {Promise<void>}
     */
    async function stop() {
        events.removeListener("registry:plugin-added", onPluginAdded);
        if (!started) {
            return;
        }
        stopping = true;
        try {
            await plugin.stop();
        } catch (err) {
            log.warn(log._("coordination.stop-failed", {error: err.toString()}));
        }
        if (typeof unsubscribePlugin === "function") {
            unsubscribePlugin();
        }
        unsubscribePlugin = null;
        started = false;
        plugin = null;
    }

    /**
     * @return {boolean} whether this instance is the leader; `false` before the
     *   start, after the stop and without a connection to the coordinator
     */
    function isLeader() {
        if (!started) {
            return false;
        }
        try {
            return plugin.isLeader() === true;
        } catch (err) {
            return false;
        }
    }

    /**
     * Adds a listener of leadership changes.
     * @param {Node} [node] - the listener is removed when the node closes
     * @param {(isLeader: boolean) => void} listener
     * @return {() => void} removes the listener
     */
    function onLeaderChange(node, listener) {
        if (typeof node === "function" && listener === undefined) {
            listener = node;
            node = null;
        }
        if (typeof listener !== "function") {
            throw new TypeError("listener must be a function");
        }
        listeners.add(listener);
        let removed = false;
        const remove = function() {
            if (!removed) {
                removed = true;
                listeners.delete(listener);
                if (node && typeof node.removeListener === "function") {
                    node.removeListener("close", remove);
                }
            }
        };
        if (node && typeof node.on === "function") {
            node.on("close", remove);
        }
        return remove;
    }

    /**
     * Claims a key in the whole cluster for ttlMs.
     * @param {string} key - recommended prefix: the node id
     * @param {number} ttlMs
     * @return {Promise<Claim|null>} `null` - do not run the task; a rejection
     *   (no connection, not started) - do not run the task
     */
    function claim(key, ttlMs) {
        const err = local.checkClaimArgs(key, ttlMs);
        if (err) {
            return Promise.reject(err);
        }
        if (!started) {
            return Promise.reject(createError("coordination.not-started", "coordination is not started"));
        }
        const current = plugin;
        return new Promise(function(resolve) { resolve(current.claim(key, ttlMs)) }).then(function(result) {
            return result || null;
        });
    }

    /**
     * Claims one of `limit` slots of a named pool, for example to limit how
     * many instances reload their flows at the same time
     * (`deploy.reload.concurrency`). The slots are keys `slot:<name>:<i>`
     * claimed in order; the first one claimed is returned.
     *
     * ```js
     * const slot = await runtime.coordination.claimSlot("reload", concurrency, ttlMs);
     * if (slot) { try { ...; } finally { await slot.release() } } else { // wait and retry }
     * ```
     *
     * @param {string} name - name of the pool
     * @param {number} limit - number of slots (integer >= 1)
     * @param {number} ttlMs - ttl of the claim; renew it for longer work
     * @return {Promise<Claim|null>} `null` - all slots are taken; a rejection - no connection
     */
    async function claimSlot(name, limit, ttlMs) {
        if (typeof name !== "string" || name.length === 0) {
            throw new TypeError("slot name must be a non-empty string");
        }
        if (!Number.isInteger(limit) || limit < 1) {
            throw new TypeError("slot limit must be an integer >= 1");
        }
        for (let i = 0; i < limit; i++) {
            const result = await claim("slot:" + name + ":" + i, ttlMs);
            if (result) {
                return result;
            }
        }
        return null;
    }

    /**
     * @return {{plugin: string, local: boolean}} the active plugin, without its options
     */
    function info() {
        return {plugin: pluginId, local: isLocal};
    }

    const api = Object.freeze({
        isLeader: isLeader,
        onLeaderChange: onLeaderChange,
        claim: claim,
        info: info
    });

    return {
        PLUGIN_TYPE: PLUGIN_TYPE,
        start: start,
        resign: resign,
        stop: stop,
        isLeader: isLeader,
        onLeaderChange: onLeaderChange,
        claim: claim,
        claimSlot: claimSlot,
        info: info,
        /** The node api: `RED.coordination` */
        api: api
    };
}

module.exports = createCoordination();
module.exports.createCoordination = createCoordination;
